import { ApplicationConfig, mergeApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideRouter, Router, UrlSerializer, withComponentInputBinding, withDebugTracing } from '@angular/router';
import { routes } from './app.routes';
import { provideClientHydration, withEventReplay } from '@angular/platform-browser';
import { cleanUrlSerializer } from './utils/clean-url-serializer';
import { provideServerRendering } from '@angular/ssr';
import { serverRoutes } from './app.routes.server';
import { provideHttpClient, withInterceptors } from '@angular/common/http';
import { httpNonceInterceptor } from './utils/http-nonce-intercepter';
import { ServiceRequesterService } from './utils/restServiceClient/service-requester.service';
import { NestjsRequester } from './utils/restServiceClient/nestjs-requester';

function initializeRoute(router: Router) {
  return () => {
    const savedRoute = localStorage.getItem('saved_route');
    // Ensure we don't infinitely redirect or override a direct deep link
    if (savedRoute && savedRoute !== '/' && window.location.pathname === '/') {
      return router.navigateByUrl(savedRoute);
    }
    return Promise.resolve(true);
  };
}

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideHttpClient(withInterceptors([httpNonceInterceptor])),
    provideRouter(routes, withComponentInputBinding()), provideClientHydration(withEventReplay()),//,withDebugTracing()
    /*{
      provide: APP_INITIALIZER,
      useFactory: initializeRoute,
      deps: [Router],
      multi: true,
    },*/
    { provide: UrlSerializer, useClass: cleanUrlSerializer },
    { provide: ServiceRequesterService, useClass: NestjsRequester }

  ]
};

const serverConfig: ApplicationConfig = {
  providers: [
    provideServerRendering(),
    provideRouter(serverRoutes) // Hooks into the hybrid rendering engine
  ]
};

export const config = mergeApplicationConfig(appConfig, serverConfig);
