import { HttpClient, HttpContext, HttpHeaders, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { catchError, Observable, of, tap } from 'rxjs';
import { USE_ENCRYPTED_PARAMS } from '../http-nonce-intercepter';
import { UserSupportModel } from '../../user/interfaces/user-model';

@Injectable({
  providedIn: 'root',
})
export class NestjsRequester {

  private _nonceObject: { Controller: string, Method: string, Nonce: string } | null = null;
  private _paramObject: any | null = null;
  private _apiUrl: string = 'api/';//http://localhost:8881/wp-json/devatrip-users/v1/nonce/
  private _context: HttpContext = new HttpContext().set(USE_ENCRYPTED_PARAMS, true);

  constructor(
    private _http: HttpClient
  ) { }

  getCachedNonce(): string {
    return this._nonceObject?.Nonce || '';
  }

  getNonce(str: string, param: Object, ctrl: String): Observable<any> {
    console.log('here in init service method of nestjs requester');
    this._paramObject = param;
    switch (str) {
      case 'validateLogin':
        return this.handleLogin();
      case 'updateUserData':
        return this.handleUpdateUserData();
      case 'registeruser':
        return this.handleRegisterUser();
      case 'getUserData':
        return this.handleGetUser();
      case 'updateUserSettings':
        return this.handleUpdateUserSettings();
      default:
        return of(null);
    }
  }

  mailSupport(params: UserSupportModel): Observable<any> {
    const url = this._apiUrl + 'support';

    return this._http.post<any>(url, params)
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('getUser', []))
      );
  }

  private handleRegisterUser(): Observable<any> {

    const url = this._apiUrl + 'users';

    return this._http.post<any>(url, this._paramObject, { context: this._context })
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('RegisterUser', []))
      );
  }

  private handleGetUser(): Observable<any>{
    //const url = this._apiUrl + 'users';
    const params = new HttpParams()
      .set('id', this._paramObject['id'])

    return this._http.get<any>(this._apiUrl + 'users/user',  { params: params, context: this._context })
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('UpdateUserData', []))
      );
  }

  private handleUpdateUserData(): Observable<any> {
    const url = this._apiUrl + 'users';

    return this._http.patch<any>(url, this._paramObject, { context: this._context })
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('UpdateUserData', []))
      );
  }

  private handleUpdateUserSettings(): Observable<any>{
    const url = this._apiUrl + 'users/settings';

    return this._http.patch<any>(url, this._paramObject, { context: this._context })
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('UpdateUserData', []))
      );
  }

  private handleLogin(): Observable<any> {

    const params = new HttpParams()
      .set('useremail', this._paramObject['useremail'])
      .set('userpassword', this._paramObject['userpassword'])
    return this._http.get<any>(this._apiUrl + 'users/login', { params: params, context: this._context })
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('Login', []))
      );
  }

  private getLoginData(): Observable<any> {
    //console.log('here in calling service method');
    /*let paramString = '';
    for(var i in this._paramObject){
        paramString += (i +'=' + this._paramObject[i]+"&");
    }
    const url = this._apiUrl + ''+this._nonceObject['controller'] + '/' + this._nonceObject['method'] + '/?' + paramString + 'nonce=' + this._nonceObject['nonce'];
    return this._http.get<any>(url)
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data)) ),
        catchError(this.handleError('getUser', []))
    );*/

    const httpOptions = {
      headers: new HttpHeaders({
        'Content-Type': 'application/json'
      })
    };

    const url = this._apiUrl + 'user';
    //this._apiUrl + 'user/?useremail=' + this._paramObject['useremail'] + '&userpassword=' + this._paramObject['userpassword'] + '&nonce=' + this._nonceObject?.Nonce;
    //this._apiUrl + ''+this._nonceObject?.Controller + '/' + this._nonceObject?.Method + '/?' + this._paramObject?.toString() + 'nonce=' + this._nonceObject?.Nonce;
    return this._http.post<any>(url, this._paramObject, httpOptions)
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('getUser', []))
      );
  }

  //getRestData(data,'devtrip.dev@gmail.com','Asdfg@123')
  /**
  * Handle Http operation that failed.
  * Let the app continue.
  * @param operation - name of the operation that failed
  * @param result - optional value to return as the observable result
  */
  private handleError<T>(operation = 'operation', result?: T) {
    return (error: any): Observable<T> => {

      // TODO: send the error to remote logging infrastructure
      console.error(error); // log to console instead

      // TODO: better job of transforming error for user consumption
      console.log(`${operation} failed: ${error.message}`);

      // Let the app keep running by returning an empty result.
      return of(result as T);
    };
  }
}
