import { Component, HostListener, inject, OnInit, signal } from '@angular/core';
import { NavigationEnd, Router, RouterOutlet } from '@angular/router';
import { filter } from 'rxjs';
import { RouteDataService } from './utils/routeData/route-data-service';
import { AuthenticationService } from './user/userservices/authentication.service';

@Component({
  selector: 'app-root',
  imports: [RouterOutlet],
  templateUrl: './app.html',
  styleUrl: './app.css'
})
export class App implements OnInit {

  protected readonly title = signal('Devatrip Devotional');
  //inject

  private routerData = inject(RouteDataService);
  private userData = inject(AuthenticationService)

  @HostListener('window:beforeunload', ['$event'])
  clearLocalStorage(event: BeforeUnloadEvent): void {
    // Clear a specific key
    if(!this.userData.currentUserValue?.credential){
      localStorage.removeItem('currentUser');
    }

    // Or clear everything entirely
    // localStorage.clear(); 
  }

  ngOnInit() {
    this.routerData.collectData();
    
    /*this.router.events.pipe(
      filter(event => event instanceof NavigationEnd)
    ).toPromise().then(() => {});*/

    /*this.router.events.subscribe((event) => {
      if (event instanceof NavigationEnd) {
        // Skip saving root or empty paths if needed, or save everything
        localStorage.setItem('saved_route_param', event.urlAfterRedirects);
      }
    });*/
  }



}
