import { HttpInterceptorFn, HttpRequest, HttpHandlerFn, HttpParams, HttpContextToken } from '@angular/common/http';
import { inject } from '@angular/core';
import { switchMap, take } from 'rxjs/operators';
import { ServiceRequesterService } from './restServiceClient/service-requester.service';
import * as CryptoJS from 'crypto-js';

export const USE_ENCRYPTED_PARAMS = new HttpContextToken<boolean>(() => true);


export const httpNonceInterceptor: HttpInterceptorFn = (req: HttpRequest<unknown>, next: HttpHandlerFn) => {

  if (req.context.get(USE_ENCRYPTED_PARAMS) === false) {
    return next(req);
  }
  const nonceService = inject(ServiceRequesterService);

  //console.log('httpNonceInterceptor called for request: ', req.url, ' method: ', req.method, ' params: ', req.params.keys(), req.params.get('userpassword'), ' post param: ', req.body);

  // Only apply nonces to mutating requests (POST, PUT, DELETE)
  const mutableMethods = ['POST', 'PUT', 'DELETE', 'PATCH', 'GET'];

  if (!mutableMethods.includes(req.method)) {
    return next(req);
  }

  const cachedNonce = nonceService.getCachedNonce();

  const secretKey = CryptoJS.enc.Utf8.parse('98569874563214569874563582695874');
  const iv = CryptoJS.enc.Utf8.parse('5698741254126358');
  const cryptoConfig = {
    iv: iv,
    mode: CryptoJS.mode.CBC,
    padding: CryptoJS.pad.Pkcs7
  };

  let params = new HttpParams();
  if (req.params.keys().length > 0) {
    req.params.keys().forEach(key => {
      const encryptedValue = CryptoJS.AES.encrypt(req.params.get(key) || '', secretKey, cryptoConfig).toString();
      params = params.set(key, encryptedValue);
    });
  }
  //console.log('------------------>',params)

  let encryptedBody = CryptoJS.AES.encrypt(JSON.stringify(req.body), secretKey, cryptoConfig).toString();

  const clonedReq = req.clone({
    setHeaders: {
      'X-API-NONCE': cachedNonce,
      'Content-Type': 'application/json'
    },
    body: { encryptedBody: encryptedBody },
    params: params
  });

  return next(clonedReq);

  /*if (cachedNonce) {
    // 1. If we have a cached nonce, attach it to the header
    const clonedReq = req.clone({
      setHeaders: { 'X-XSRF-NONCE': cachedNonce }
    });
    // Clear it so it isn't accidentally reused
    //nonceService.clearNonce(); 
    return next(clonedReq);
  } else {
    // 2. If no nonce is cached, fetch one first, then proceed with the request
    return nonceService.getNewNonce().pipe(
      take(1),
      switchMap(freshNonce => {
        const clonedReq = req.clone({
          setHeaders: { 'X-XSRF-NONCE': freshNonce }
        });
        nonceService.clearNonce();
        return next(clonedReq);
      })
    );
  }*/
};
